import{z as n,x as s,o as A,c as p,q as o,j as B,D as l,d as a,s as i,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"经验回放与批处理","description":"","frontmatter":{"title":"经验回放与批处理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-replay-batching.md","filePath":"llm/rlsys-replay-batching.md","lastUpdated":1791063341000}'),d={name:"llm/rlsys-replay-batching.md"};function c(m,E,h,C,D,F){const r=s("Mermaid");return A(),p("div",null,[E[2]||(E[2]=o('<h1 id="经验回放与批处理" tabindex="-1">经验回放与批处理 <a class="header-anchor" href="#经验回放与批处理" aria-label="Permalink to &quot;经验回放与批处理&quot;">​</a></h1><div class="epigraph"><p>语言模型的 RL 大多号称 on-policy，于是「回放缓冲」缩水成一条传送带——但传送带的分拣与丢弃规则，决定了训练器吃进去的是什么。</p><footer>—— 据 Shao 等 2024（GRPO）与 DAPO 的组内口径整理</footer></div><p><a href="/llm/rlsys-refmodel-kl">上一课</a>把 KL 挂好位置，经验四件套齐了：序列、行为 logprob、奖励、KL。本课写它们如何变成一次参数更新：组批、分拣、过滤与打包。经典 RL 的经验回放在这里只剩残影——on-policy 训练基本现采现用——但组基线、动态采样与序列打包把「怎么组一批」变成了有真实杠杆的工程问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个更新步吃一批序列，这批怎么来？语言模型 RL 的答案几乎总是：同批提示、组内多采样。</p><p><span class="marginnote">数字实例看零方差组：\\(G=8\\) 时一组 8 个响应全对（或全错），组内基线消掉后每个优势都是 0——8 条序列的前向反向白算。任务准确率 90% 时，一组全对的概率约 \\(0.9^8\\approx43\\%\\)，意味着近半算力在产出零梯度：这就是「有效组占比」要单独监控的原因。</span></p><p>GRPO 对每个提示采一组 \\(G\\) 个响应，用组内统计当基线算优势——组是这个算法族的原子结构，组批必须保住它。缺口有三。其一，组内全对或全错时优势全零，这一组白采，而且随训练进展越采越多。其二，响应长短悬殊：pad 浪费与截断失真二选一。其三，批次间优势尺度漂移，学习率与 clip 范围的物理含义跟着漂。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缓冲区按四列存：token、行为 logprob、奖励、版本号。组批流水线四步。第一步按提示聚合组，组内算基线与优势（<a href="/llm/grpo">GRPO</a> 与 <a href="/llm/rloo">RLOO</a> 的差别只是基线取组均值还是留一均值）。第二步过滤：零方差组不带梯度，动态采样补采新提示补齐批次（<a href="/llm/dynamic-sampling-rl">动态采样</a>）；超长响应要么截断要么整条丢弃（<a href="/llm/overlong-filtering">过长过滤</a>），且丢弃规则必须与奖励设计一致——若截断响应仍送 RM 打分，模型会学会把话说一半骗分。第三步尺度控制：批内优势白化钉住尺度，让学习率与 clip 跨实验可比（<a href="/llm/reward-whitening">奖励归一化与白化</a>「只做一层」的纪律在这里生效）。第四步打包：多条序列拼进 micro-batch 最小化 pad，梯度累积凑出全局批。凡混入旧版本的样本（异步补采、多轮复用），必须带截断重要性权重，不能假装还在 on-policy。</p><p><span class="marginnote">「on-policy」翻译成大白话：用来更新的样本必须出自「当前这一版策略」之手，梯度公式才严格成立；样本一旦是老版本生成的，就带「陈旧度」，要靠重要性权重打折扣补偿。像生鲜直送与冷冻库存的区别——直送免校正，库存越久，越要贴标签补手续。</span></p><p><span class="marginnote">准确率升到高位后，零方差组占比可能过半：全对（或全错）的组优势为零，算力照烧、梯度为零。监控「有效组占比」与「有效 token 占比」，比监控 loss 更早暴露这层浪费。</span></p>',11)),(A(),B(t,null,{default:l(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUF%5B%22%E7%BB%8F%E9%AA%8C%E7%BC%93%E5%86%B2%EF%BC%9Atoken%2Flogprob%2F%E5%A5%96%E5%8A%B1%2F%E7%89%88%E6%9C%AC%22%5D%20--%3E%20GRP%5B%22%E6%8C%89%E6%8F%90%E7%A4%BA%E8%81%9A%E5%90%88%E7%BB%84%EF%BC%9A%E7%BB%84%E5%9F%BA%E7%BA%BF%E4%B8%8E%E4%BC%98%E5%8A%BF%22%5D%0A%20%20GRP%20--%3E%20FILT%5B%22%E8%BF%87%E6%BB%A4%EF%BC%9A%E9%9B%B6%E6%96%B9%E5%B7%AE%E7%BB%84%E8%A1%A5%E9%87%87%E3%80%81%E8%BF%87%E9%95%BF%E4%B8%A2%E5%BC%83%22%5D%0A%20%20FILT%20--%3E%20WH%5B%22%E6%89%B9%E5%86%85%E4%BC%98%E5%8A%BF%E7%99%BD%E5%8C%96%EF%BC%88%E5%8F%AA%E5%81%9A%E4%B8%80%E5%B1%82%EF%BC%89%22%5D%0A%20%20STALE%5B%22%E6%97%A7%E7%89%88%E6%9C%AC%E6%A0%B7%E6%9C%AC%EF%BC%9A%E6%88%AA%E6%96%AD%20IS%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20WH%0A%20%20WH%20--%3E%20PACK%5B%22%E5%BA%8F%E5%88%97%E6%89%93%E5%8C%85%20%E2%86%92%20micro-batch%20%E2%86%92%20%E6%A2%AF%E5%BA%A6%E7%B4%AF%E7%A7%AF%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("「回放」在语言模型 RL 里的真实身份是版本控制问题。严格 on-policy 意味着缓冲深度为零：采完即用，用完即弃，重要性权重恒为 1。任何打破它的机制——异步生成、动态补采、多 epoch 复用——都让缓冲里出现版本混合，此时训练的数学前提从策略梯度变成离策略修正，每条样本要乘行为版与当前版比值的截断权重，方差随之上升（"),e("a",{href:"/llm/truncated-importance-sampling"},"截断重要性采样"),a("）。所以批处理流水线的每个过滤器都有双重身份：既是算力优化（少算零梯度样本），也是分布控制（不让偏差样本混进批次）。把它们当纯性能开关随手开关，改的不是速度而是算法。")],-1)),(A(),B(t,null,{default:l(()=>[i(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20O%5B%22%E4%B8%A5%E6%A0%BC%20on-policy%EF%BC%9A%E7%BC%93%E5%86%B2%E6%B7%B1%E5%BA%A6%200%22%5D%20--%3E%7C%22%E9%87%87%E5%AE%8C%E5%8D%B3%E7%94%A8%22%7C%20W1%5B%22%E9%87%8D%E8%A6%81%E6%80%A7%E6%9D%83%E9%87%8D%20%3D%201%EF%BC%8C%E6%97%A0%E5%81%8F%E5%B7%AE%22%5D%0A%20%20O%20--%3E%7C%22%E5%BC%82%E6%AD%A5%E7%94%9F%E6%88%90%20%2F%20%E5%8A%A8%E6%80%81%E8%A1%A5%E9%87%87%20%2F%20%E5%A4%9A%20epoch%20%E5%A4%8D%E7%94%A8%22%7C%20MIX%5B%22%E7%BC%93%E5%86%B2%E9%87%8C%E5%87%BA%E7%8E%B0%E7%89%88%E6%9C%AC%E6%B7%B7%E5%90%88%22%5D%0A%20%20MIX%20--%3E%20MATH%5B%22%E6%95%B0%E5%AD%A6%E5%89%8D%E6%8F%90%E5%8F%98%E4%B8%BA%E7%A6%BB%E7%AD%96%E7%95%A5%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20MATH%20--%3E%20ISW%5B%22%E6%AF%8F%E6%9D%A1%E6%A0%B7%E6%9C%AC%E4%B9%98%E6%88%AA%E6%96%AD%20IS%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20ISW%20--%3E%20V%5B%22%E6%96%B9%E5%B7%AE%E4%B8%8A%E5%8D%87%EF%BC%9A%E7%BC%93%E5%86%B2%E8%B6%8A%E6%B7%B1%E3%80%81%E7%89%88%E6%9C%AC%E8%B6%8A%E6%97%A7%E8%B6%8A%E8%B4%B5%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>组批不创造信息：零方差组只能丢弃或补采，不能凭空补梯度，补采的前提是还采得出方差——上游是任务难度分布（<a href="/llm/rl-difficulty-curriculum">难度课程</a>）的事。白化抹掉「这批任务普遍偏易或偏难」的信息，看训练进展要回到原始奖励曲线。打包与梯度累积的数值效应（等效大 batch）是另一层超参，别与算法改进混为一谈。</p><p><span class="marginnote">常见误区：初学者容易把「序列打包」「梯度累积」当算法改进来报喜——它们只是把算力排满、把批凑大的工程手段，等效于调大 batch 这一超参。真做算法改进（换基线、加过滤）时，也要先钉死这些工程旋钮，两者混在一起动，就说不清功劳归谁。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>on-policy 让回放缓冲缩成传送带，但组批规则（组结构、过滤、白化、打包）每项都同时是性能与算法开关。</li><li>GRPO 族以组为原子：基线取自组内统计，组批必须按提示聚合，不能跨组混算。</li><li>零方差组与过长响应是两类必过滤样本；丢弃规则必须与奖励设计一致，否则教模型钻空子。</li><li>任何版本混合（异步、补采、复用）都要补截断 IS 权重；装作 on-policy 是静默偏差。</li><li>出处：Shao 等 2024（GRPO）；Ahmadian 等 2024（RLOO）；Yu 等 DAPO（动态采样）；据 verl 实现整理。</li></ul>',5))])}const _=n(d,[["render",c]]);export{u as __pageData,_ as default};
